    if hi - lo < k:
        return 0
    count = [0] * 26
    for i in range(lo, hi):
        count[ord(s[i]) - ord("a")] += 1
    start = lo
    best = 0
    split = False
    for i in range(lo, hi):
        if count[ord(s[i]) - ord("a")] < k:
            split = True
            best = max(best, best_block(s, k, start, i))
            start = i + 1
    if not split:
        return hi - lo
    return max(best, best_block(s, k, start, hi))

