#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int bestBlock(const string& s, int k, int lo, int hi) {
    if (hi - lo < k) return 0;
    int count[26] = {0};
    for (int i = lo; i < hi; i++) count[s[i] - 'a']++;
    int start = lo, best = 0;
    bool split = false;
    for (int i = lo; i < hi; i++) {
        if (count[s[i] - 'a'] < k) {
            split = true;
            best = max(best, bestBlock(s, k, start, i));
            start = i + 1;
        }
    }
    if (!split) return hi - lo;
    return max(best, bestBlock(s, k, start, hi));
}

int main() {
    long long k;
    cin >> k;
    string s;
    cin >> s;

    cout << bestBlock(s, k, 0, s.size()) << "\n";

